public partial class Program
{
    private readonly IConfiguration _configuration;

    public Program(IConfiguration configuration) => _configuration = configuration;

    public void ConfigureServices(IServiceCollection services)
    {
        services.AddInfrastructure(_configuration);
        services.AddIdentityModule(_configuration);
        services.AddCandidatesModule(_configuration);
        services.AddEmployerProfileModule(_configuration);
        services.AddReferenceDataModule(_configuration);
        services.AddJobPostingsModule(_configuration);
        services.AddPaymentsModule(_configuration);
        services.AddNotificationsModule(_configuration);

        var rateOptions = _configuration.GetSection(RateLimitingOptions.SectionName)
            .Get<RateLimitingOptions>() ?? new RateLimitingOptions();

        services.AddRateLimiter(options =>
        {
            options.AddPolicy(IranJob.Modules.Identity.Infrastructure.Extensions.ServiceCollectionExtensions.AuthRateLimitPolicy, httpContext =>
                RateLimitPartition.GetFixedWindowLimiter(
                    partitionKey: httpContext.Connection.RemoteIpAddress?.ToString() ?? "unknown",
                    factory: _ => new FixedWindowRateLimiterOptions
                    {
                        PermitLimit = rateOptions.PermitLimit,
                        Window = TimeSpan.FromSeconds(rateOptions.WindowSeconds),
                        QueueLimit = 0
                    }));

            options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
        });

        services.AddScoped<ISystemInfoService, SystemInfoService>();

        services.AddControllers()
            .AddApplicationPart(typeof(AuthController).Assembly)
            .AddApplicationPart(typeof(CandidateProfileController).Assembly)
            .AddApplicationPart(typeof(EmployerProfileController).Assembly)
            .AddApplicationPart(typeof(JobCategoriesController).Assembly)
            .AddApplicationPart(typeof(EmployerJobsController).Assembly)
            .AddApplicationPart(typeof(PaymentController).Assembly)
            .AddApplicationPart(typeof(NotificationsController).Assembly);

        services.AddEndpointsApiExplorer();

        services
            .AddApiVersioning(options =>
            {
                options.DefaultApiVersion = new ApiVersion(1, 0);
                options.AssumeDefaultVersionWhenUnspecified = true;
                options.ReportApiVersions = true;
            })
            .AddApiExplorer(options =>
            {
                options.GroupNameFormat = "'v'VVV";
                options.SubstituteApiVersionInUrl = true;
            });

        services.AddSwaggerGen(options =>
        {
            options.SwaggerDoc("v1", new OpenApiInfo
            {
                Title = "IranJob API",
                Version = "v1",
                Description = "IranJob recruitment platform API"
            });

            options.AddSecurityDefinition("Bearer", new OpenApiSecurityScheme
            {
                Description = "JWT Authorization header using the Bearer scheme.",
                Name = "Authorization",
                In = ParameterLocation.Header,
                Type = SecuritySchemeType.Http,
                Scheme = "bearer",
                BearerFormat = "JWT"
            });

            options.AddSecurityRequirement(new OpenApiSecurityRequirement
            {
                {
                    new OpenApiSecurityScheme
                    {
                        Reference = new OpenApiReference
                        {
                            Type = ReferenceType.SecurityScheme,
                            Id = "Bearer"
                        }
                    },
                    Array.Empty<string>()
                }
            });
        });

        services.AddCors(options =>
        {
            options.AddPolicy("Frontend", policy =>
            {
                policy.WithOrigins("http://localhost:4200")
                    .AllowAnyHeader()
                    .AllowAnyMethod()
                    .AllowCredentials()
                    .WithExposedHeaders("X-CSRF-TOKEN", "X-Correlation-ID");
            });
        });
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        // The IApplicationBuilder passed here is actually a WebApplication at runtime
        // (when used via UseStartup inside ConfigureWebHostDefaults), but the compiler
        // only sees IApplicationBuilder — so cast for the WebApplication-specific
        // extension methods.
        var webApp = (WebApplication)app;

        if (env.IsDevelopment())
        {
            app.UseSwagger();
            app.UseSwaggerUI(options =>
            {
                options.SwaggerEndpoint("/swagger/v1/swagger.json", "IranJob API v1");
            });
        }

        app.UseExceptionHandler();
        app.UseCors("Frontend");
        webApp.UseInfrastructureMiddleware();
        webApp.UseIdentityModule();

        webApp.MapControllers();

        webApp.MapHealthChecks("/health", new Microsoft.AspNetCore.Diagnostics.HealthChecks.HealthCheckOptions
        {
            Predicate = registration => registration.Tags.Contains("live")
        });

        webApp.MapHealthChecks("/health/ready", new Microsoft.AspNetCore.Diagnostics.HealthChecks.HealthCheckOptions
        {
            Predicate = registration => registration.Tags.Contains("ready")
        });

        var uploadsPath = Path.Combine(env.ContentRootPath, "uploads");

        app.UseStaticFiles();

        app.UseStaticFiles(new StaticFileOptions
        {
            FileProvider = new PhysicalFileProvider(uploadsPath),
            RequestPath = "/uploads"
        });
    }
}
